function twoSum(nums, target) { const seen = new Map();
  for (let i = 0; i < nums.length; i++) {
    const need = target - nums[i];
    if (seen.has(need)) return [seen.get(need), i];
    seen.set(nums[i], i);
  } return [];
}

function isValid(s) { const stack = [];
  const pairs = { ')': '(', ']': '[', '}': '{' }; for (const c of s) {
    if (c === '(' || c === '[' || c === '{') { stack.push(c);
    } else if (stack.pop() !== pairs[c]) { return false;
    } }
  return stack.length === 0;
}

function reverseList(head) { let prev = null;
  while (head) { const next = head.next;
    head.next = prev;
    prev = head;
    head = next;
  } return prev;
}

function maxSubArray(nums) { let best = nums[0];
  let cur = nums[0];
  for (let i = 1; i < nums.length; i++) {
    cur = Math.max(nums[i], cur + nums[i]);
    best = Math.max(best, cur);
  } return best;
}

function mergeTwoLists(a, b) {
  const dummy = { val: 0, next: null }; let tail = dummy;
  while (a && b) { if (a.val <= b.val) { tail.next = a;
      a = a.next; } else { tail.next = b;
      b = b.next; } tail = tail.next;
  } tail.next = a || b;
  return dummy.next; }

function maxProfit(prices) { let best = 0;
  let low = prices[0];
  for (const price of prices) {
    best = Math.max(best, price - low);
    low = Math.min(low, price);
  } return best;
}

function isPalindrome(s) {
  const clean = s.toLowerCase().replace(/[^a-z0-9]/g, '');
  return clean === clean.split('').reverse().join('');
}

function climbStairs(n) {
  let a = 1;
  let b = 1;
  for (let i = 0; i < n - 1; i++) {
    [a, b] = [b, a + b];
  } return b;
}

function binarySearch(arr, target) { let lo = 0;
  let hi = arr.length - 1;
  while (lo <= hi) { const mid = Math.floor((lo + hi) / 2);
    if (arr[mid] === target) return mid;
    if (arr[mid] < target) lo = mid + 1;
    else hi = mid - 1;
  } return -1; }

function singleNumber(nums) {
  return nums.reduce((acc, n) => acc ^ n, 0);
}

function containsDuplicate(nums) {
  const seen = new Set();
  for (const n of nums) {
    if (seen.has(n)) return true;
    seen.add(n);
  } return false;
}

function majorityElement(nums) { let count = 0;
  let candidate = 0;
  for (const n of nums) {
    if (count === 0) candidate = n;
    count += n === candidate ? 1 : -1;
  } return candidate;
}

function moveZeroes(nums) {
  let write = 0;
  for (const n of nums) {
    if (n !== 0) nums[write++] = n;
  } while (write < nums.length) nums[write++] = 0;
  return nums;
}

function productExceptSelf(nums) { const n = nums.length;
  const res = new Array(n).fill(1);
  let left = 1;
  for (let i = 0; i < n; i++) { res[i] = left;
    left *= nums[i]; } let right = 1;
  for (let i = n - 1; i >= 0; i--) { res[i] *= right;
    right *= nums[i]; } return res; }

function mergeIntervals(intervals) { intervals.sort((a, b) => a[0] - b[0]);
  const merged = [];
  for (const [start, end] of intervals) {
    const last = merged[merged.length - 1];
    if (last && start <= last[1]) last[1] = Math.max(last[1], end);
    else merged.push([start, end]);
  } return merged; }

function groupAnagrams(strs) { const groups = new Map();
  for (const s of strs) {
    const key = s.split('').sort().join('');
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(s);
  } return [...groups.values()];
}

function longestCommonPrefix(strs) { let prefix = strs[0] || '';
  for (const s of strs) { while (!s.startsWith(prefix)) {
      prefix = prefix.slice(0, -1);
      if (!prefix) return '';
    } }
  return prefix;
}

function romanToInt(s) {
  const values = { I: 1, V: 5, X: 10, L: 50, C: 100, D: 500, M: 1000 }; let total = 0;
  for (let i = 0; i < s.length; i++) {
    const value = values[s[i]];
    total += value < values[s[i + 1]] ? -value : value;
  } return total;
}

function isPalindromeNumber(x) { if (x < 0) return false;
  let reversed = 0;
  let copy = x;
  while (copy > 0) { reversed = reversed * 10 + (copy % 10);
    copy = Math.floor(copy / 10);
  } return reversed === x;
}

function plusOne(digits) {
  for (let i = digits.length - 1; i >= 0; i--) {
    if (digits[i] < 9) { digits[i]++;
      return digits;
    } digits[i] = 0;
  } return [1, ...digits];
}

function removeDuplicates(nums) {
  let write = 0;
  for (const n of nums) {
    if (write === 0 || n !== nums[write - 1]) nums[write++] = n;
  }
  return write;
}

function rotateArray(nums, k) {
  const n = nums.length;
  k %= n;
  return nums.slice(n - k).concat(nums.slice(0, n - k));
}

function missingNumber(nums) {
  const n = nums.length;
  return (n * (n + 1)) / 2 - nums.reduce((a, b) => a + b, 0);
}

function fizzBuzz(n) { const result = [];
  for (let i = 1; i <= n; i++) {
    if (i % 15 === 0) result.push('FizzBuzz');
    else if (i % 3 === 0) result.push('Fizz');
    else if (i % 5 === 0) result.push('Buzz');
    else result.push(String(i));
  } return result; }

function isPowerOfTwo(n) {
  return n > 0 && (n & (n - 1)) === 0;
}

function hammingWeight(n) {
  let count = 0;
  while (n !== 0) {
    count += n & 1;
    n >>>= 1;
  } return count;
}

function reverseString(s) {
  return s.split('').reverse().join('');
}

function reverseInteger(x) {
  const sign = x < 0 ? -1 : 1;
  const reversed = Number(String(Math.abs(x)).split('').reverse().join('')) * sign;
  if (reversed < -(2 ** 31) || reversed > 2 ** 31 - 1) return 0;
  return reversed;
}

function lengthOfLastWord(s) {
  const words = s.trim().split(/\s+/);
  return words.length ? words[words.length - 1].length : 0;
}

function strStr(haystack, needle) {
  if (!needle) return 0;
  for (let i = 0; i <= haystack.length - needle.length; i++) {
    if (haystack.slice(i, i + needle.length) === needle) return i;
  }
  return -1;
}

function addBinary(a, b) { let carry = 0;
  let result = ''; let i = a.length - 1; let j = b.length - 1;
  while (i >= 0 || j >= 0 || carry) { let total = carry;
    if (i >= 0) total += Number(a[i--]);
    if (j >= 0) total += Number(b[j--]);
    result = String(total % 2) + result;
    carry = Math.floor(total / 2); } return result; }

function mySqrt(x) { if (x < 2) return x;
  let lo = 1; let hi = Math.floor(x / 2);
  let answer = 0;
  while (lo <= hi) { const mid = Math.floor((lo + hi) / 2);
    if (mid * mid <= x) { answer = mid;
      lo = mid + 1; } else { hi = mid - 1; } }
  return answer; }

function titleToNumber(columnTitle) {
  let result = 0;
  for (const c of columnTitle) {
    result = result * 26 + (c.charCodeAt(0) - 64);
  }
  return result;
}

function isHappy(n) {
  const seen = new Set();
  while (n !== 1 && !seen.has(n)) {
    seen.add(n);
    n = String(n).split('').reduce((sum, d) => sum + Number(d) ** 2, 0);
  } return n === 1;
}

function isIsomorphic(s, t) { if (s.length !== t.length) return false;
  const forward = new Map(); const backward = new Map();
  for (let i = 0; i < s.length; i++) { const a = s[i];
    const b = t[i];
    if (forward.has(a) && forward.get(a) !== b) return false;
    if (backward.has(b) && backward.get(b) !== a) return false;
    forward.set(a, b); backward.set(b, a); } return true; }

function wordPattern(pattern, s) { const words = s.split(' ');
  if (pattern.length !== words.length) return false;
  const forward = new Map(); const backward = new Map();
  for (let i = 0; i < words.length; i++) { const a = pattern[i];
    const b = words[i]; if (forward.has(a) && forward.get(a) !== b) return false;
    if (backward.has(b) && backward.get(b) !== a) return false;
    forward.set(a, b); backward.set(b, a); } return true; }

function intersection(nums1, nums2) {
  const set = new Set(nums1);
  return nums2.filter((n) => set.has(n)).filter((n, i, arr) => arr.indexOf(n) === i);
}

function sortedSquares(nums) {
  return nums.map((n) => n * n).sort((a, b) => a - b);
}

function maxDepth(root) {
  if (!root) return 0;
  return 1 + Math.max(maxDepth(root.left), maxDepth(root.right));
}

function isSameTree(p, q) {
  if (!p && !q) return true;
  if (!p || !q || p.val !== q.val) return false;
  return isSameTree(p.left, q.left) && isSameTree(p.right, q.right);
}

function invertTree(root) {
  if (!root) return null;
  [root.left, root.right] = [invertTree(root.right), invertTree(root.left)];
  return root;
}

function isSymmetric(root) {
  const mirror = (a, b) => {
    if (!a && !b) return true;
    if (!a || !b || a.val !== b.val) return false;
    return mirror(a.left, b.right) && mirror(a.right, b.left);
  }; return !root || mirror(root.left, root.right);
}

function diameterOfBinaryTree(root) { let best = 0;
  const depth = (node) => { if (!node) return 0;
    const left = depth(node.left);
    const right = depth(node.right);
    best = Math.max(best, left + right);
    return 1 + Math.max(left, right); }; depth(root);
  return best; }

function isBalanced(root) { const height = (node) => { if (!node) return 0;
    const left = height(node.left);
    const right = height(node.right);
    if (left < 0 || right < 0 || Math.abs(left - right) > 1) return -1;
    return 1 + Math.max(left, right);
  }; return height(root) >= 0;
}

function hasPathSum(root, targetSum) {
  if (!root) return false;
  if (!root.left && !root.right) return root.val === targetSum;
  return hasPathSum(root.left, targetSum - root.val)
    || hasPathSum(root.right, targetSum - root.val);
}

function lowestCommonAncestor(root, p, q) {
  while (root) {
    if (p.val < root.val && q.val < root.val) root = root.left;
    else if (p.val > root.val && q.val > root.val) root = root.right;
    else return root;
  } return null;
}

function searchInsert(nums, target) { let lo = 0;
  let hi = nums.length;
  while (lo < hi) { const mid = Math.floor((lo + hi) / 2);
    if (nums[mid] < target) lo = mid + 1;
    else hi = mid;
  } return lo;
}

function twoSumSorted(numbers, target) { let left = 0;
  let right = numbers.length - 1;
  while (left < right) { const total = numbers[left] + numbers[right];
    if (total === target) return [left + 1, right + 1];
    if (total < target) left++;
    else right--;
  } return []; }

function lengthOfLongestSubstring(s) { const last = new Map();
  let start = 0;
  let best = 0;
  for (let i = 0; i < s.length; i++) { const c = s[i];
    if (last.has(c) && last.get(c) >= start) start = last.get(c) + 1;
    last.set(c, i);
    best = Math.max(best, i - start + 1); } return best; }

function maxArea(height) { let left = 0;
  let right = height.length - 1;
  let best = 0;
  while (left < right) {
    best = Math.max(best, Math.min(height[left], height[right]) * (right - left));
    if (height[left] < height[right]) left++;
    else right--; } return best; }
